use crate::record::Record;
use std::io::{Result, Write};

pub fn render(rows: &[Record], out: &mut dyn Write) -> Result<()> {
    writeln!(out, "timestamp,level,message")?;
    for r in rows {
        writeln!(out, "{},{},{}", r.timestamp, r.level, escape(&r.message))?;
    }
    Ok(())
}

fn escape(field: &str) -> String {
    if field.contains(',') || field.contains('"') {
        format!("\"{}\"", field.replace('"', "\"\""))
    } else {
        field.to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::escape;

    #[test]
    fn leaves_plain_fields_alone() {
        assert_eq!(escape("server started"), "server started");
    }

    #[test]
    fn quotes_fields_with_commas() {
        assert_eq!(escape("slow query, 812ms"), "\"slow query, 812ms\"");
    }
}

